-- 20261105_repair_staging_tenant_uuids_rollback.sql   (GENERATED by scripts/generate-staging-tenant-uuid-repair.ts — do not edit by hand)
--
-- STAGING ONLY. EMERGENCY ROLLBACK of the repair: restores the malformed 00000000-2711-0000-0000-… tenant ids. This re-introduces ids the API rejects; use only to return to the exact pre-repair state.
-- Never apply to production. Applied by an operator in the Supabase SQL editor (staging project) — not by the app.
--
-- Properties
--   * One transaction: all or nothing.
--   * Idempotent: a second run finds nothing to move and succeeds without changes.
--   * Order: copy the tenant rows to their new ids (FK targets first) → repoint EVERY public uuid column and jsonb/text
--     value that references the old ids → prove no reference remains → delete the old tenant rows.
--   * Fails closed: aborts (rolls back) if the old org is not the 'Gravix Staging QA' fixture, or any reference remains.
--   * Excluded from the sweep on purpose: the tenant rows' own primary keys (handled by copy/delete) and
--     profiles.user_id (FKs auth.users; legacy synthetic auth users are retired by a separate optional file).
begin;
set local lock_timeout = '15s';
set local statement_timeout = '120s';

-- 0. Guards ---------------------------------------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from public.orgs where id = '00000000-2711-4000-8000-000000000002')
     and not exists (select 1 from public.orgs where id = '00000000-2711-4000-8000-000000000002' and name = 'Gravix Staging QA') then
    raise exception 'refusing: org 00000000-2711-4000-8000-000000000002 exists but is not the Gravix Staging QA fixture';
  end if;
  if not exists (select 1 from public.orgs where id in ('00000000-2711-4000-8000-000000000002', '00000000-2711-0000-0000-000000000002')) then
    raise exception 'refusing: neither the source nor the target fixture org exists (wrong project?)';
  end if;
end $$;

-- 1. Copy the tenant rows to their new ids (parents before children) ------------------------------------------------
-- the old row keeps its unique slug until deleted: park it so the copy can take the real one
update public.tmcs set slug = slug || '--repair-' || substr(id::text, 25)
 where id = '00000000-2711-4000-8000-000000000001' and slug !~ '--repair-' and not exists (select 1 from public.tmcs where id = '00000000-2711-0000-0000-000000000001');
insert into public.tmcs
select (jsonb_populate_record(null::public.tmcs, to_jsonb(t) || jsonb_build_object('id', '00000000-2711-0000-0000-000000000001') || jsonb_build_object('slug', regexp_replace(t.slug, '--repair-.*$', '')))).*
  from public.tmcs t where t.id = '00000000-2711-4000-8000-000000000001'
on conflict (id) do nothing;

insert into public.orgs
select (jsonb_populate_record(null::public.orgs, to_jsonb(t) || jsonb_build_object('id', '00000000-2711-0000-0000-000000000002'))).*
  from public.orgs t where t.id = '00000000-2711-4000-8000-000000000002'
on conflict (id) do nothing;

-- the old row keeps its unique slug until deleted: park it so the copy can take the real one
update public.companies set slug = slug || '--repair-' || substr(id::text, 25)
 where id = '00000000-2711-4000-8000-000000000003' and slug !~ '--repair-' and not exists (select 1 from public.companies where id = '00000000-2711-0000-0000-000000000003');
insert into public.companies
select (jsonb_populate_record(null::public.companies, to_jsonb(t) || jsonb_build_object('id', '00000000-2711-0000-0000-000000000003', 'tmc_id', '00000000-2711-0000-0000-000000000001') || jsonb_build_object('slug', regexp_replace(t.slug, '--repair-.*$', '')))).*
  from public.companies t where t.id = '00000000-2711-4000-8000-000000000003'
on conflict (id) do nothing;

insert into public.reps
select (jsonb_populate_record(null::public.reps, to_jsonb(t) || jsonb_build_object('id', '00000000-2711-0000-0000-00000000000c', 'org_id', '00000000-2711-0000-0000-000000000002', 'company_id', '00000000-2711-0000-0000-000000000003'))).*
  from public.reps t where t.id = '00000000-2711-4000-8000-00000000000c'
on conflict (id) do nothing;

insert into public.org_settings
select (jsonb_populate_record(null::public.org_settings, to_jsonb(t) || jsonb_build_object('org_id', '00000000-2711-0000-0000-000000000002'))).*
  from public.org_settings t where t.org_id = '00000000-2711-4000-8000-000000000002'
on conflict (org_id) do nothing;

-- 2. Repoint every reference ----------------------------------------------------------------------------------------
do $$
declare
  m record; c record; n bigint; moved bigint := 0;
begin
  for m in select * from (values
    ('00000000-2711-4000-8000-000000000001'::uuid, '00000000-2711-0000-0000-000000000001'::uuid),
    ('00000000-2711-4000-8000-000000000002'::uuid, '00000000-2711-0000-0000-000000000002'::uuid),
    ('00000000-2711-4000-8000-000000000003'::uuid, '00000000-2711-0000-0000-000000000003'::uuid),
    ('00000000-2711-4000-8000-00000000000c'::uuid, '00000000-2711-0000-0000-00000000000c'::uuid)
  ) as v(old_id, new_id)
  loop
    -- uuid columns (every public base table), except the tenant rows' own keys and profiles.user_id
    for c in
      select cl.table_name, cl.column_name
        from information_schema.columns cl
        join information_schema.tables tb on tb.table_schema = cl.table_schema and tb.table_name = cl.table_name and tb.table_type = 'BASE TABLE'
       where cl.table_schema = 'public' and cl.data_type = 'uuid'
         and (cl.table_name, cl.column_name) not in (('tmcs','id'),('orgs','id'),('companies','id'),('reps','id'),('org_settings','org_id'),('profiles','user_id'))
    loop
      execute format('update public.%I set %I = $2 where %I = $1', c.table_name, c.column_name, c.column_name) using m.old_id, m.new_id;
      get diagnostics n = row_count; moved := moved + n;
    end loop;
    -- json/jsonb values that embed the id as text (e.g. sparring_sessions.meta)
    for c in
      select cl.table_name, cl.column_name
        from information_schema.columns cl
        join information_schema.tables tb on tb.table_schema = cl.table_schema and tb.table_name = cl.table_name and tb.table_type = 'BASE TABLE'
       where cl.table_schema = 'public' and cl.data_type = 'jsonb'
    loop
      execute format('update public.%I set %I = replace(%I::text, $1, $2)::jsonb where %I::text like ''%%'' || $1 || ''%%''', c.table_name, c.column_name, c.column_name, c.column_name) using m.old_id::text, m.new_id::text;
      get diagnostics n = row_count; moved := moved + n;
    end loop;
  end loop;
  raise notice 'repointed % reference(s)', moved;
end $$;

-- 3. Prove nothing still references the ids being retired ------------------------------------------------------------
do $$
declare c record; n bigint; bad text := '';
begin
  for c in
    select cl.table_name, cl.column_name, cl.data_type
      from information_schema.columns cl
      join information_schema.tables tb on tb.table_schema = cl.table_schema and tb.table_name = cl.table_name and tb.table_type = 'BASE TABLE'
     where cl.table_schema = 'public' and cl.data_type in ('uuid','jsonb','json','text','character varying')
       and (cl.table_name, cl.column_name) not in (('tmcs','id'),('orgs','id'),('companies','id'),('reps','id'),('org_settings','org_id'),('profiles','user_id'))
  loop
    execute format('select count(*) from public.%I where %I::text = any (array[''00000000-2711-4000-8000-000000000001'', ''00000000-2711-4000-8000-000000000002'', ''00000000-2711-4000-8000-000000000003'', ''00000000-2711-4000-8000-00000000000c'']) ',
                   c.table_name, c.column_name) into n;
    if n > 0 then bad := bad || format(' %s.%s=%s', c.table_name, c.column_name, n); end if;
  end loop;
  if bad <> '' then raise exception 'repair aborted — references remain:%', bad; end if;
end $$;

-- 4. Retire the old tenant rows (children first) ---------------------------------------------------------------------
delete from public.org_settings where org_id = '00000000-2711-4000-8000-000000000002';
delete from public.reps         where id     = '00000000-2711-4000-8000-00000000000c';
delete from public.companies    where id     = '00000000-2711-4000-8000-000000000003';
delete from public.orgs         where id     = '00000000-2711-4000-8000-000000000002';
delete from public.tmcs         where id     = '00000000-2711-4000-8000-000000000001';

-- 5. Post-conditions ------------------------------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from public.orgs      where id = '00000000-2711-0000-0000-000000000002')     then raise exception 'post-check failed: org 00000000-2711-0000-0000-000000000002 missing'; end if;
  if not exists (select 1 from public.companies where id = '00000000-2711-0000-0000-000000000003') then raise exception 'post-check failed: company 00000000-2711-0000-0000-000000000003 missing'; end if;
  if not exists (select 1 from public.tmcs      where id = '00000000-2711-0000-0000-000000000001')     then raise exception 'post-check failed: tmc 00000000-2711-0000-0000-000000000001 missing'; end if;
end $$;

commit;
